INSERT INTO evidence (id, opportunity_id, source_id, source_url, excerpt, confidence, created_at) VALUES
  ('a2000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001', 'e1000000-0000-0000-0000-000000000001', 'crunchbase.com/organization/nexford-dynamics', 'Nexford Dynamics raised $45M in Series C funding led by Accel Partners, targeting automated assembly line expansion.', 'high', '2026-10-01T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000001', 'e1000000-0000-0000-0000-000000000005', 'industryweek.com/nexford-automation', 'Nexford Dynamics announced a new automated assembly line product line scheduled for Q1 2027 launch, targeting automotive OEMs.', 'medium', '2026-10-05T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000002', 'e1000000-0000-0000-0000-000000000003', 'news.google.com/brightwell-doe-grant', 'Brightwell Energy awarded $120M Department of Energy grant for grid-scale battery storage innovation.', 'high', '2026-10-02T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000003', 'e1000000-0000-0000-0000-000000000003', 'news.google.com/meridian-acquires-medai', 'Meridian Health Systems acquired MedAI Systems for $85M to expand AI-powered diagnostic capabilities across its hospital network.', 'high', '2026-10-03T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000003', 'e1000000-0000-0000-0000-000000000007', 'gartner.com/health-ai-2026', 'Gartner report identifies Meridian as a leader in healthcare AI adoption, citing 40% reduction in diagnostic errors.', 'medium', '2026-10-05T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000004', 'e1000000-0000-0000-0000-000000000004', 'sec.gov/edgar/vantix-rfp', 'Vantix Logistics filed 8-K disclosing $8M capital expenditure plan for warehouse automation system procurement.', 'high', '2026-10-04T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000005', 'e1000000-0000-0000-0000-000000000003', 'news.google.com/corvus-dod-contract', 'Corvus Aerospace won a $200M Department of Defense contract for next-generation unmanned aerial vehicle components.', 'high', '2026-10-05T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000005', 'e1000000-0000-0000-0000-000000000002', 'linkedin.com/sales/corvus-expansion', 'Corvus Aerospace building new 80,000 sq ft production facility in Everett, WA to meet increased DoD demand.', 'medium', '2026-10-06T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000007', 'e1000000-0000-0000-0000-000000000006', 'techcrunch.com/pinnacle-d2c', 'Pinnacle Retail launched a new direct-to-consumer platform, exiting 40% of physical retail locations to focus on e-commerce.', 'high', '2026-10-07T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000007', 'e1000000-0000-0000-0000-000000000004', 'sec.gov/edgar/pinnacle-q3', 'Pinnacle Retail Q3 earnings report shows 34% YoY revenue growth driven by online channel expansion and D2C pivot.', 'medium', '2026-10-09T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000006', 'e1000000-0000-0000-0000-000000000003', 'news.google.com/halcyon-digital', 'Halcyon Financial Group announced a comprehensive digital transformation initiative to modernize compliance and risk systems.', 'medium', '2026-10-06T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000016', 'e1000000-0000-0000-0000-000000000003', 'news.google.com/terranova-phase3', 'Terranova Biotech Phase III clinical trial for lead oncology drug shows statistically significant improvement in progression-free survival.', 'high', '2026-10-08T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000017', 'e1000000-0000-0000-0000-000000000006', 'techcrunch.com/quantum-edge-processor', 'Quantum Edge Computing released a new edge AI processor claiming 3x performance improvement over competitors.', 'medium', '2026-10-09T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000017', 'e1000000-0000-0000-0000-000000000003', 'news.google.com/quantum-aws-partnership', 'Quantum Edge announced strategic partnership with AWS to deliver edge computing services on Amazon EC2.', 'medium', '2026-10-12T12:00:00Z'),
  ('a2000000-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000010', 'e1000000-0000-0000-0000-000000000003', 'news.google.com/stellarcomm-5g', 'Stellarcomm Networks announced 5G network expansion across 14 states with $300M infrastructure investment over 18 months.', 'high', '2026-10-10T12:00:00Z')
